import { setContext, getContext, untrack } from "svelte";
import { SvelteMap } from "svelte/reactivity";
import type { Props, ToastId } from "./index.js";

const CONTEXT_ID = "toaster-context";

class UseCompCtx {
	/** Where the toasts stack */
	position: NonNullable<Props["position"]> = $state("bottom-right");
	/** Keeps the toasts spread out */
	expand = $state(false);
	/** Number of toasts shown at once */
	visibleToasts = $state(3);
	/** Milliseconds each toast stays open, unless it sets its own */
	duration = $state(4000);
	/** Shows a close button on every toast, unless it sets its own */
	closeButton = $state(false);
	/** Tints error toasts, unless a toast sets its own */
	richColors = $state(false);
	/** Padding, text, and icon size of the toasts */
	size: UiSize = $state("md");
	/** Corner radius of the toasts */
	rounded: UiRounded = $state("lg");
	/** Whether the pointer is over the list */
	hovered = $state(false);
	/** Whether focus is inside the list */
	focused = $state(false);
	/** Whether a toast is being pressed or swiped */
	interacting = $state(false);
	/** Whether the page is in a background tab */
	pageHidden = $state(false);
	/** Measured content height of each toast in pixels, by id */
	heights = new SvelteMap<ToastId, number>();
	/** Whether the toasts are spread out instead of stacked */
	expanded = $derived(this.expand || this.hovered || this.focused || this.interacting);
	/** Whether the close timers are on hold */
	paused = $derived(this.hovered || this.focused || this.interacting || this.pageHidden);
	/** Edge of the viewport the toasts enter from */
	edge = $derived(this.position.startsWith("top") ? "top" : "bottom");

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}

	/** Records a toast's content height; untracked, so the effect that reports it does not also depend on the map and loop. */
	setHeight(id: ToastId, height: number) {
		untrack(() => this.heights.set(id, height));
	}

	/** Forgets a toast's height once it unmounts. */
	removeHeight(id: ToastId) {
		untrack(() => this.heights.delete(id));
	}
}

export type CompCtxProps = Pick<InstanceType<typeof UseCompCtx>, "position" | "expand" | "visibleToasts" | "duration" | "closeButton" | "richColors" | "size" | "rounded">;

export const setCompCtx = (props: CompCtxProps) => setContext(CONTEXT_ID, new UseCompCtx(props));

export const useCompCtx = () => getContext<ReturnType<typeof setCompCtx>>(CONTEXT_ID);

import type { ToastData, ToastId, ToastOptions, ToastPromiseOptions, ToastType } from "./index.js";

// Milliseconds a closing toast stays in the list so its exit can play.
export const EXIT_DURATION = 200;

/** Every toast on the page, shared by all toasters, newest first */
class ToastState {
	/** Toasts in the list, newest first */
	toasts: ToastData[] = $state([]);
	/** Next generated id */
	#nextId = 1;

	/** Adds a toast, or updates the toast with the same id in place; returns its id. */
	add(title: string, type: ToastType, options: ToastOptions = {}) {
		const { id = this.#nextId++, ...rest } = options;
		const existing = this.toasts.find((toast) => toast.id === id);
		// If the id is already in the list: update that toast and restart its timer.
		if (existing) {
			Object.assign(existing, rest, { title, type, updatedAt: Date.now(), dismissed: false });
			return id;
		}
		this.toasts.unshift({ ...rest, id, title, type, updatedAt: Date.now(), dismissed: false });
		return id;
	}

	/** Closes one toast, or every toast when `id` is omitted; `auto` marks a close after the duration. */
	dismiss(id?: ToastId, auto = false) {
		const toasts = id === undefined ? this.toasts : this.toasts.filter((toast) => toast.id === id);
		for (const toast of toasts) {
			// If the toast is already closing: skip it, so its callbacks run once.
			if (toast.dismissed) continue;
			toast.dismissed = true;
			if (auto) toast.onAutoClose?.(toast);
			else toast.onDismiss?.(toast);
			// Remove it once the exit has played, unless an update reopened it in the meantime.
			setTimeout(() => {
				if (toast.dismissed) this.toasts = this.toasts.filter((item) => item !== toast);
			}, EXIT_DURATION);
		}
	}
}

export const toastState = new ToastState();

/** Shows a toast and returns its id; the type helpers and `promise` and `dismiss` hang off it. */
export const toast = Object.assign((title: string, options?: ToastOptions) => toastState.add(title, "default", options), {
	/** Shows a toast without an icon. */
	message: (title: string, options?: ToastOptions) => toastState.add(title, "default", options),
	/** Shows a toast with a check icon. */
	success: (title: string, options?: ToastOptions) => toastState.add(title, "success", options),
	/** Shows a toast with an info icon. */
	info: (title: string, options?: ToastOptions) => toastState.add(title, "info", options),
	/** Shows a toast with a warning icon. */
	warning: (title: string, options?: ToastOptions) => toastState.add(title, "warning", options),
	/** Shows a toast with an error icon. */
	error: (title: string, options?: ToastOptions) => toastState.add(title, "error", options),
	/** Shows a toast with a spinner that stays open until it is updated or dismissed. */
	loading: (title: string, options?: ToastOptions) => toastState.add(title, "loading", options),
	/** Shows a loading toast that turns into a success or error toast when the promise settles; returns its id. */
	promise: <T>(promise: Promise<T> | (() => Promise<T>), { loading, success, error, ...options }: ToastPromiseOptions<T>) => {
		const id = toastState.add(loading, "loading", options);
		// Accept a function so the work only starts once the toast is shown.
		const pending = typeof promise === "function" ? promise() : promise;
		pending.then(
			(value) => toastState.add(typeof success === "function" ? success(value) : success, "success", { ...options, id }),
			(reason: unknown) => toastState.add(typeof error === "function" ? error(reason) : error, "error", { ...options, id }),
		);
		return id;
	},
	/** Closes one toast by id, or every toast when the id is omitted. */
	dismiss: (id?: ToastId) => toastState.dismiss(id),
});

export { default as Toaster } from "./_.svelte";
export { toast } from "./state.svelte.js";

/** Corner of the viewport, or the middle of its top or bottom edge, that the toasts stack from */
export type ToasterPosition = "top-left" | "top-center" | "top-right" | "bottom-left" | "bottom-center" | "bottom-right";

/** Kind of toast; each kind except `default` shows its own icon */
export type ToastType = "default" | "success" | "info" | "warning" | "error" | "loading";

/** Id of a toast; pass it back to `toast` to update the toast, or to `toast.dismiss` to close it */
export type ToastId = string | number;

/** Button shown at the end of a toast */
export interface ToastAction {
	/** Button text */
	label: string;
	/** Called on click; the toast closes afterwards unless the handler calls `preventDefault` */
	onClick?: (e: MouseEvent) => void;
}

/** Settings for one toast */
export interface ToastOptions {
	/** Id of an existing toast to update in place, or a custom id for a new one */
	id?: ToastId;
	/** Muted text under the title */
	description?: string;
	/** Milliseconds before the toast closes; `Infinity` keeps it open; follows the toaster's `duration` when omitted */
	duration?: number;
	/** Whether a swipe or `toast.dismiss` can close the toast; defaults to `true` */
	dismissible?: boolean;
	/** Shows a close button in the corner; follows the toaster's `closeButton` when omitted */
	closeButton?: boolean;
	/** Tints error toasts with the destructive color; follows the toaster's `richColors` when omitted */
	richColors?: boolean;
	/** Main button, such as Undo */
	action?: ToastAction;
	/** Secondary button that closes the toast, such as Cancel */
	cancel?: ToastAction;
	/** Icon in place of the type's icon */
	icon?: Snippet;
	/** Id of the `Toaster` that shows the toast; toasts without one show in toasters without an `id` */
	toasterId?: string;
	/** Classes merged onto the toast */
	class?: string;
	/** Called when the toast is closed by a swipe, a button, or `toast.dismiss` */
	onDismiss?: (toast: ToastData) => void;
	/** Called when the toast closes after its duration */
	onAutoClose?: (toast: ToastData) => void;
}

/** A toast in the list, as the toaster reads it */
export interface ToastData extends Omit<ToastOptions, "id"> {
	/** Unique id */
	id: ToastId;
	/** Main text */
	title: string;
	/** Kind of toast, which sets its icon */
	type: ToastType;
	/** Time of the last create or update, which restarts the close timer */
	updatedAt: number;
	/** Whether the toast is closing; it plays its exit before it is removed */
	dismissed: boolean;
}

/** Messages and settings for `toast.promise`; the success and error messages can read the result */
export interface ToastPromiseOptions<T> extends Omit<ToastOptions, "id"> {
	/** Title while the promise is pending */
	loading: string;
	/** Title once the promise resolves, or a function of its value */
	success: string | ((value: T) => string);
	/** Title once the promise rejects, or a function of its error */
	error: string | ((error: unknown) => string);
}

/** Area that shows the toasts; place it once in the root layout */
export interface Props extends CompProps<"section"> {
	/** Shows only the toasts whose `toasterId` matches; leave it out for the main toaster */
	id?: string;
	/** Where the toasts stack; defaults to `bottom-right` */
	position?: ToasterPosition;
	/** Keeps the toasts spread out instead of stacked; they always spread while hovered or focused */
	expand?: boolean;
	/** Number of toasts shown at once; older ones wait behind; defaults to `3` */
	visibleToasts?: number;
	/** Milliseconds each toast stays open; defaults to `4000` */
	duration?: number;
	/** Shows a close button on every toast */
	closeButton?: boolean;
	/** Tints error toasts with the destructive color */
	richColors?: boolean;
	/** Space between spread-out toasts, and how far stacked toasts peek out, on the shared scale; defaults to `md` */
	gap?: UiSize;
	/** Padding, text, and icon size of the toasts on the shared scale; defaults to `md` */
	size?: UiSize;
	/** Corner radius of the toasts; defaults to `lg`. `pill` is a true pill that can clip the content, so use `3xl` or `4xl` to stay round */
	rounded?: UiRounded;
	/** Keys that move focus to the toasts: modifier names such as `altKey`, then a key code; defaults to Alt+T */
	hotkey?: string[];
	/** Classes merged onto the region */
	class?: CompProps<"section">["class"];
}

/** Internal toast item rendered by the toaster */
export interface ToastItemProps {
	/** The toast to show */
	toast: ToastData;
	/** Place in the stack among the toasts still open, with 0 at the front */
	index: number;
	/** Pixels from the stack edge to this toast while spread out */
	offset: number;
}

export type ToasterProps = Props;
